package eu.jodelahithit;

import com.google.common.base.Strings;
import net.runelite.client.util.ColorUtil;

import java.awt.*;

public class Utils {
    public static int getStringWidth(Graphics graphics, String text) {
        FontMetrics metrics = graphics.getFontMetrics();
        return metrics.stringWidth(text);
    }

    public static int getStringHeight(Graphics graphics) {
        FontMetrics metrics = graphics.getFontMetrics();
        return metrics.getHeight();
    }

    public static void renderTextCentered(Graphics2D graphics, int x, int y, String text, Color color) {
        if (Strings.isNullOrEmpty(text)) {
            return;
        }

        int halfWidth = graphics.getFontMetrics().stringWidth(text) / 2;

        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x - halfWidth + 1, y + 1);

        graphics.setColor(ColorUtil.colorWithAlpha(color, 255));
        graphics.drawString(text, x - halfWidth, y);
    }

    public static float clamp(float val, float min, float max) {
        return Math.max(min, Math.min(max, val));
    }

    public static float clamp01(float val) {
        return Math.max(0.0f, Math.min(1.0f, val));
    }
}

package eu.jodelahithit;

public enum WintertodtActivity {
    IDLE("what you were doing"),
    WOODCUTTING("woodcutting"),
    FLETCHING("fletching"),
    FEEDING_BRAZIER("feeding the brazier"),
    FIXING_BRAZIER("repairing the brazier"),
    LIGHTING_BRAZIER("lighting the brazier");

    private final String displayName;

    WintertodtActivity(String displayName)
    {
        this.displayName = displayName;
    }

    String getDisplayName()
    {
        return displayName;
    }
}

package eu.jodelahithit;

enum WintertodtInterruptType {
    COLD("The cold of", "Cold damage"),
    SNOWFALL("The freezing cold attack", "A snowfall attack"),
    BRAZIER("The brazier is broken and shrapnel", "Brazier shrapnel"),
    INVENTORY_FULL("Your inventory is too full", "A full inventory"),
    OUT_OF_ROOTS(null, "Running out of roots"),
    OUT_OF_KINDLING(null, "Running out of kindling"),
    FIXED_BRAZIER("You fix the brazier", null),
    LIT_BRAZIER("You light the brazier", null),
    BRAZIER_WENT_OUT("The brazier has gone out.", "The brazier going out"),
    LEVEL_UP("Congratulations, you've just advanced your", "Leveling up");

    private final String messagePrefix;
    private final String notificationText;

    WintertodtInterruptType(
            String messagePrefix,
            String notificationText) {
        this.messagePrefix = messagePrefix;
        this.notificationText = notificationText;
    }

    static WintertodtInterruptType fromMessage(String message) {
        for (WintertodtInterruptType type : values()) {
            if (type.messagePrefix != null
                    && message.startsWith(type.messagePrefix)) {
                return type;
            }
        }

        return null;
    }

    String getNotificationText() {
        return notificationText;
    }

    boolean hasNotificationText() {
        return notificationText != null;
    }
}

package eu.jodelahithit;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup("wintertodt-notifications")
public interface WintertodtNotificationsConfig extends Config
{
    @Alpha
    @ConfigItem(
            keyName = "overlayColor",
            name = "Notification color",
            description = "Set the notification overlay color",
            position = 0
    )
    default Color overlayColor() {
        return new Color(1.0f, 0.0f, 0.0f, 0.5f);
    }

    @ConfigItem(
            keyName = "notificationFlash",
            name = "Notification flash",
            description = "Flash the overlay",
            position = 1
    )
    default boolean flash() {
        return false;
    }

    @Range(
            min = 0,
            max = 2000
    )
    @Units(Units.MILLISECONDS)
    @ConfigItem(
            keyName = "notificationFade",
            name = "Fade duration",
            description = "Time taken to fade the notification in or out",
            position = 2
    )
    default int notificationFade()
    {
        return 150;
    }

    @ConfigItem(
            keyName = "showInterruptionText",
            name = "Show interruption reason",
            description = "Display what interrupted the current action on the overlay",
            position = 3
    )
    default boolean showInterruptionText()
    {
        return false;
    }

    @ConfigItem(
            keyName = "nativeNotification",
            name = "Native notification",
            description = "Send a RuneLite notification when an action is interrupted",
            position = 4
    )
    default boolean nativeNotification()
    {
        return false;
    }

    @Range(min = 0)
    @ConfigItem(
            keyName = "notificationPointThreshold",
            name = "Stop notifying at points",
            description = "Stop all plugin notifications at or above this round's points. Set to 0 to disable; use 500 for the minimum reward points.",
            position = 5
    )
    default int notificationPointThreshold()
    {
        return 0;
    }
}

package eu.jodelahithit;

import java.awt.*;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ColorUtil;

class WintertodtNotificationsOverlay extends Overlay {
    private static final long INTERRUPTION_DURATION_NANOS = TimeUnit.SECONDS.toNanos(2);

    private static final float TEXT_COLOR_LERP = 0.75f;
    private static final int FLASH_HALF_PERIOD_CYCLES = 20;

    private final Client client;
    private final WintertodtNotificationsPlugin plugin;
    private final WintertodtNotificationsConfig config;

    private long lastFrameNanos;
    private float fadeValue;

    private int flashStartCycle;
    private boolean flashReadyPreviously;

    private long interruptionUntilNanos;
    private String interruptionText = "";

    @Inject
    private WintertodtNotificationsOverlay(Client client, WintertodtNotificationsPlugin plugin, WintertodtNotificationsConfig config) {
        super(plugin);
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);

        this.client = client;
        this.plugin = plugin;
        this.config = config;
    }

    private Color getFadedColor(Color input, boolean targetVisible) {
        long now = System.nanoTime();

        if (lastFrameNanos == 0L) {
            lastFrameNanos = now;
        }

        long elapsedNanos = now - lastFrameNanos;
        lastFrameNanos = now;

        int fadeDurationMillis = config.notificationFade();

        if (fadeDurationMillis <= 0) {
            fadeValue = targetVisible ? 1.0f : 0.0f;
        } else {
            long fadeDurationNanos =
                    TimeUnit.MILLISECONDS.toNanos(fadeDurationMillis);

            float change = elapsedNanos / (float) fadeDurationNanos;

            fadeValue += targetVisible ? change : -change;
            fadeValue = Utils.clamp01(fadeValue);
        }

        return new Color(
                input.getRed(),
                input.getGreen(),
                input.getBlue(),
                Math.round(input.getAlpha() * fadeValue)
        );
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.isPointThresholdReached()) {
            reset();
            return null;
        }

        boolean targetVisible = plugin.shouldRenderOverlay();

        Color configuredColor = config.overlayColor();
        Color fadedColor = getFadedColor(configuredColor, targetVisible);
        Color textColor = ColorUtil.colorLerp(
                Color.WHITE,
                configuredColor,
                TEXT_COLOR_LERP
        );

        boolean flashReady = targetVisible && (config.notificationFade() == 0 || fadeValue >= 1.0f);

        if (flashReady && !flashReadyPreviously) {
            flashStartCycle = client.getGameCycle();
        }

        flashReadyPreviously = flashReady;

        boolean flashHidden = false;

        if (flashReady && config.flash()) {
            int elapsedCycles = client.getGameCycle() - flashStartCycle;

            flashHidden = elapsedCycles % (FLASH_HALF_PERIOD_CYCLES * 2) >= FLASH_HALF_PERIOD_CYCLES;
        }

        long now = System.nanoTime();
        boolean interruptionActive = interruptionUntilNanos - now > 0L;

        int canvasWidth = client.getCanvasWidth();
        int canvasHeight = client.getCanvasHeight();

        if ((targetVisible || fadeValue > 0.001f) && !flashHidden) {
            Color previousColor = graphics.getColor();

            graphics.setColor(fadedColor);
            graphics.fillRect(0, 0, canvasWidth, canvasHeight);

            graphics.setColor(previousColor);
        }

        if (interruptionActive) {
            Utils.renderTextCentered(
                    graphics,
                    canvasWidth / 2, canvasHeight / 8 + Utils.getStringHeight(graphics),
                    interruptionText,
                    textColor
            );
        }

        return null;
    }

    void showInterruption(String text) {
        interruptionText = text;
        interruptionUntilNanos = System.nanoTime() + INTERRUPTION_DURATION_NANOS;
    }

    void reset() {
        lastFrameNanos = 0L;
        fadeValue = 0.0f;
        flashReadyPreviously = false;
        interruptionUntilNanos = 0L;
        interruptionText = "";
    }
}

package eu.jodelahithit;

import com.google.inject.Provides;

import javax.inject.Inject;

import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.Notifier;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;


import static eu.jodelahithit.WintertodtInterruptType.*;

import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

@PluginDescriptor(
        name = "Wintertodt Notifications",
        description = "Visual notifications for Wintertodt",
        tags = {"notifications", "wintertodt"}
)
public class WintertodtNotificationsPlugin extends Plugin {
    private static final int MOVEMENT_COOLDOWN_TICKS = 2;
    private static final int ACTION_TIMEOUT_TICKS = 5;
    private static final int IDLE_ANIMATION = -1;

    private static final int WINTERTODT_REGION = 6462;
    private boolean isInWintertodt;
    private WintertodtActivity currentActivity = WintertodtActivity.IDLE;
    private int timerValue;
    private LocalPoint lastPlayerLocation;

    private int ticksSinceMovement = MOVEMENT_COOLDOWN_TICKS;
    private int lastActionTick = -1;

    private int previousRootCount = -1;
    private int previousKindlingCount = -1;

    @Inject
    Client client;

    @Inject
    private WintertodtNotificationsConfig config;

    @Inject
    private WintertodtNotificationsOverlay overlay;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private Notifier nativeNotifier;

    @Provides
    WintertodtNotificationsConfig getConfig(ConfigManager configManager) {
        return configManager.getConfig(WintertodtNotificationsConfig.class);
    }

    private void resetState() {
        overlay.reset();
        isInWintertodt = false;
        currentActivity = WintertodtActivity.IDLE;
        timerValue = -1;
        lastPlayerLocation = null;
        lastActionTick = -1;
        ticksSinceMovement = MOVEMENT_COOLDOWN_TICKS;
        previousRootCount = -1;
        previousKindlingCount = -1;
    }


    @Override
    protected void startUp() {
        resetState();
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(overlay);
        resetState();
    }

    private boolean isInWintertodtRegion() {
        if (client.getLocalPlayer() != null) {
            return client.getLocalPlayer().getWorldLocation().getRegionID() == WINTERTODT_REGION;
        }

        return false;
    }

    private void initializeInventoryCounts() {
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);

        if (inventory == null) {
            previousRootCount = 0;
            previousKindlingCount = 0;
            return;
        }

        previousRootCount = inventory.count(ItemID.WINT_BRUMA_ROOT);

        previousKindlingCount = inventory.count(ItemID.WINT_BRUMA_KINDLING);
    }


    @Subscribe
    public void onGameTick(GameTick gameTick) {
        if (!isInWintertodtRegion()) {
            if (isInWintertodt) {
                resetState();
            }

            return;
        }

        Player player = client.getLocalPlayer();

        if (!isInWintertodt) {
            resetState();
            isInWintertodt = true;

            timerValue = client.getVarbitValue(VarbitID.WINT_TRANSMIT_RESPAWNDELAY);

            initializeInventoryCounts();
        }

        updateMovementState(player);
        checkActionTimeout(player);
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (isInWintertodt && event.getVarbitId() == VarbitID.WINT_TRANSMIT_RESPAWNDELAY) {
            timerValue = event.getValue();
        }
    }

    private void updateMovementState(Player player) {
        LocalPoint playerLocation = player.getLocalLocation();

        if (!playerLocation.equals(lastPlayerLocation)) {
            ticksSinceMovement = 0;
        } else {
            ticksSinceMovement = Math.min(
                    ticksSinceMovement + 1,
                    MOVEMENT_COOLDOWN_TICKS);
        }

        lastPlayerLocation = playerLocation;
    }

    private void checkActionTimeout(Player player) {
        if (currentActivity == WintertodtActivity.IDLE || player.getAnimation() != IDLE_ANIMATION || lastActionTick < 0) {
            return;
        }

        int elapsedTicks = client.getTickCount() - lastActionTick;

        if (elapsedTicks >= ACTION_TIMEOUT_TICKS) {
            currentActivity = WintertodtActivity.IDLE;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage chatMessage) {
        if (!isInWintertodt) {
            return;
        }

        ChatMessageType chatMessageType = chatMessage.getType();

        if (chatMessageType != ChatMessageType.GAMEMESSAGE && chatMessageType != ChatMessageType.SPAM) {
            return;
        }

        String message = chatMessage.getMessageNode().getValue();

        if (message.startsWith("You carefully fletch the root")) {
            ItemContainer inventory = client.getItemContainer(InventoryID.INV);

            if (inventory != null && inventory.count(ItemID.WINT_BRUMA_ROOT) > 0) {
                setActivity(WintertodtActivity.FLETCHING);
            }

            return;
        }

        WintertodtInterruptType interruptType = WintertodtInterruptType.fromMessage(message);

        if (interruptType == null) {
            return;
        }

        boolean hadActiveActivity = currentActivity != WintertodtActivity.IDLE;
        boolean isDamageInterruption = interruptType == COLD || interruptType == SNOWFALL || interruptType == BRAZIER;
        boolean wasInterrupted = hadActiveActivity && (!isDamageInterruption || currentActivity != WintertodtActivity.WOODCUTTING);

        if (wasInterrupted) {
            interruptCurrentActivity(interruptType);
        }
    }

    private void interruptCurrentActivity(WintertodtInterruptType interruptType) {
        if (currentActivity == WintertodtActivity.IDLE) {
            return;
        }

        WintertodtActivity interruptedActivity = currentActivity;

        if (interruptType.hasNotificationText() && !isPointThresholdReached()) {
            String message = interruptType.getNotificationText() + " stopped " + interruptedActivity.getDisplayName();

            if (config.showInterruptionText()) {
                overlay.showInterruption(message);
            }

            if (config.nativeNotification()) {
                nativeNotifier.notify("Wintertodt: " + message);
            }
        }

        currentActivity = WintertodtActivity.IDLE;
    }

    @Subscribe
    public void onAnimationChanged(final AnimationChanged event) {
        if (!isInWintertodt) {
            return;
        }

        final Player local = client.getLocalPlayer();

        if (event.getActor() != local) {
            return;
        }

        final int animId = local.getAnimation();
        switch (animId) {
            case AnimationID.HUMAN_WOODCUTTING_BRONZE_AXE:
            case AnimationID.HUMAN_WOODCUTTING_IRON_AXE:
            case AnimationID.HUMAN_WOODCUTTING_STEEL_AXE:
            case AnimationID.HUMAN_WOODCUTTING_BLACK_AXE:
            case AnimationID.HUMAN_WOODCUTTING_MITHRIL_AXE:
            case AnimationID.HUMAN_WOODCUTTING_ADAMANT_AXE:
            case AnimationID.HUMAN_WOODCUTTING_RUNE_AXE:
            case AnimationID.HUMAN_WOODCUTTING_GILDED_AXE:
            case AnimationID.HUMAN_WOODCUTTING_DRAGON_AXE:
            case AnimationID.HUMAN_WOODCUTTING_TRAILBLAZER_AXE_NO_INFERNAL:
            case AnimationID.HUMAN_WOODCUTTING_INFERNAL_AXE:
            case AnimationID.HUMAN_WOODCUTTING_3A_AXE:
            case AnimationID.HUMAN_WOODCUTTING_CRYSTAL_AXE:
            case AnimationID.HUMAN_OPENHEAVYCHEST:
            case AnimationID.HUMAN_WOODCUTTING_TRAILBLAZER_RELOADED_AXE_NO_INFERNAL:
            case AnimationID.HUMAN_WOODCUTTING_TRAILBLAZER_AXE:
            case AnimationID.HUMAN_WOODCUTTING_TRAILBLAZER_RELOADED_AXE:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_BRONZE:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_IRON:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_STEEL:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_BLACK:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_MITHRIL:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_ADAMANT:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_RUNE:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_DRAGON:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_CRYSTAL:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_CRYSTAL_INACTIVE:
            case AnimationID.FORESTRY_2H_AXE_CHOPPING_3A:
                setActivity(WintertodtActivity.WOODCUTTING);
                break;

            case AnimationID.HUMAN_FLETCHING:
                setActivity(WintertodtActivity.FLETCHING);
                break;

            case AnimationID.HUMAN_PICKUPTABLE:
                setActivity(WintertodtActivity.FEEDING_BRAZIER);
                break;

            case AnimationID.HUMAN_CREATEFIRE:
                setActivity(WintertodtActivity.LIGHTING_BRAZIER);
                break;

            case AnimationID.HUMAN_POH_BUILD:
            case AnimationID.HUMAN_POH_BUILD_IMCANDO_HAMMER:
                setActivity(WintertodtActivity.FIXING_BRAZIER);
                break;
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        final ItemContainer container = event.getItemContainer();
        if (!isInWintertodt || container != client.getItemContainer(InventoryID.INV)) {
            return;
        }

        int numRoots = container.count(ItemID.WINT_BRUMA_ROOT);
        int numKindling = container.count(ItemID.WINT_BRUMA_KINDLING);

        WintertodtInterruptType depletionType = null;

        if (currentActivity == WintertodtActivity.FLETCHING && numRoots == 0) {
            depletionType = WintertodtInterruptType.OUT_OF_ROOTS;
        } else if (currentActivity == WintertodtActivity.FEEDING_BRAZIER) {
            boolean rootsRanOut = previousRootCount > 0 && numRoots == 0 && numRoots < previousRootCount;

            boolean kindlingRanOut = previousKindlingCount > 0 && numKindling == 0 && numKindling < previousKindlingCount;

            if (kindlingRanOut) {
                depletionType = WintertodtInterruptType.OUT_OF_KINDLING;
            } else if (rootsRanOut) {
                depletionType = WintertodtInterruptType.OUT_OF_ROOTS;
            }
        }

        previousRootCount = numRoots;
        previousKindlingCount = numKindling;

        if (depletionType != null) {
            interruptCurrentActivity(depletionType);
        }
    }

    private void setActivity(WintertodtActivity activity) {
        currentActivity = activity;
        lastActionTick = client.getTickCount();
        ticksSinceMovement = MOVEMENT_COOLDOWN_TICKS;
    }

    public boolean shouldRenderOverlay() {
        return isInWintertodt && currentActivity == WintertodtActivity.IDLE && timerValue == 0 && ticksSinceMovement >= MOVEMENT_COOLDOWN_TICKS
                && !isPointThresholdReached();
    }

    boolean isPointThresholdReached() {
        int threshold = config.notificationPointThreshold();
        if (!isInWintertodt || threshold <= 0) {
            return false;
        }

        Widget pointsWidget = client.getWidget(InterfaceID.WintStatus.POINTS);
        if (pointsWidget == null || pointsWidget.getText() == null) {
            return false;
        }

        // The game's points widget includes a label, line break and color tags.
        String points = Text.removeTags(pointsWidget.getText()).replaceAll("[^0-9]", "");
        try {
            return Integer.parseInt(points) >= threshold;
        } catch (NumberFormatException ex) {
            return false;
        }
    }
}

